macro_rules! commands {
    ($( $name:ident ($op:literal) { $( $field:ident: $ty:ty ),* } => $run:path; )*) => {
        #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
        #[serde(tag = "op")]
        pub enum RegisteredCommand {
            $(#[serde(rename = $op)] $name { $( $field: $ty ),* },)*
        }
        impl RegisteredCommand {
            pub fn recognizes(op: &str) -> bool { matches!(op, $($op)|*) }
            pub fn has_field(op: &str, field: &str) -> bool {
                match op { $($op => [$(stringify!($field)),*].contains(&field),)* _ => false }
            }
            pub(crate) fn run(&self, w: &mut Work<'_>) -> Result<(), EditError> {
                match self { $(Self::$name { $($field),* } => $run(w, $($field),*),)* }
            }
        }
        pub fn typescript() -> String {
            let variants = vec![$({
                // Zero-field commands do not push fields; the same macro also emits commands with fields.
                #[allow(unused_mut)]
                let mut fields = vec![format!("op: '{}'", $op)];
                $( fields.push(format!("{}: {}", stringify!($field), <$ty as WireType>::typescript())); )*
                format!("  | {{ {} }}", fields.join("; "))
            }),*];
            format!("// Generated by folio-edit; do not edit.\nexport type RegisteredEditCommand =\n{}\n", variants.join("\n"))
        }
        #[cfg(test)]
        fn documented_fields() -> Vec<(&'static str, Vec<(&'static str, &'static str)>)> {
            vec![$(($op, vec![$((stringify!($field), stringify!($ty))),*])),*]
        }
    }
}

