impl crate::Editor {
    pub fn footnote_options(&self) -> Result<BTreeMap<String, String>, EditError> {
        let source = self.part("Resources/Preferences.xml").ok_or_else(|| EditError::new("notFound", "Preferences.xml"))?;
        folio_idml::footnotes::settings(source).map_err(|e| EditError::new("xml", e))
    }
}

