/// Type ▸ Fill with Placeholder Text: the engine has chosen how much text fits (it needs the composition, which the
/// editor does not have), so the command carries the text; empty means nothing was fitted.
fn fill_placeholder(w: &mut Work<'_>, story: &str, at: &usize, text: &str) -> Result<(), EditError> {
    if text.is_empty() { return Ok(()); }
    crate::text::insert(w, story, *at, text)
}

impl WireType for folio_model::traps::Preset { fn typescript()->String { "import('../features/traps/types').TrapPreset".into() } }

/// Glyphs panel: one glyph of a face inserted by glyph id (the host has supplied the glyph table of the face).
fn insert_glyph(w: &mut Work<'_>, story: &str, at: &usize, family: &str, style: &str, glyph: &usize) -> Result<(), EditError> {
    crate::text::insert_glyph(w, story, *at, family, style, *glyph)
}

/// Edit ▸ Find/Change ▸ Glyph ▸ Change / Change All (the host has supplied the glyph tables of both faces).
// The registry passes each wire field separately; retain that command signature.
#[allow(clippy::too_many_arguments)]
fn glyph_replace(w: &mut Work<'_>, find_family: &str, find_style: &str, find_glyph: &usize, scope: &str, story: &str, start: &usize, end: &usize,
    change_family: &str, change_style: &str, change_glyph: &usize) -> Result<(), EditError> {
    let find = crate::text::GlyphQuery { family: find_family.into(), style: find_style.into(), glyph_id: *find_glyph, scope: scope.into(),
        story: (!story.is_empty()).then(|| story.to_owned()), start: *start, end: Some(*end) };
    crate::text::replace_glyph(w, &find, change_family, change_style, *change_glyph)
}
impl WireType for BTreeMap<String, Vec<Vec<String>>> { fn typescript() -> String { "Record<string, string[][]>".into() } }
impl WireType for serde_json::Value { fn typescript() -> String { "unknown".into() } }
impl WireType for Option<crate::ClipSettings> { fn typescript() -> String { "{threshold?: number | null; tolerance?: number | null; inset?: number | null; invert?: boolean | null; insideEdges?: boolean | null; restrictToFrame?: boolean | null; highResolution?: boolean | null; pathName?: string | null; index?: number | null} | null".into() } }
impl WireType for Option<Vec<crate::ClipPath>> { fn typescript() -> String { "{points: [[number, number], [number, number], [number, number]][]; open?: boolean}[] | null".into() } }
impl WireType for Option<serde_json::Value> { fn typescript() -> String { "unknown".into() } }
impl WireType for Option<BTreeMap<String, serde_json::Value>> { fn typescript() -> String { "Record<string, unknown> | undefined".into() } }
impl WireType for Vec<crate::indexes::sort_options::SortGroupChange> { fn typescript() -> String { "{name: string; include?: boolean | null; priority?: number | null; header_type?: string | null}[]".into() } }

fn break_table_style_link(w: &mut Work<'_>, table: &str) -> Result<(), EditError> {
    crate::ops::break_table_style_link(w, table)
}
fn break_cell_style_link(w: &mut Work<'_>, table: &str, cells: &[[usize; 2]]) -> Result<(), EditError> {
    crate::ops::break_cell_style_link(w, table, cells)
}
fn clear_cell_style_attributes(w: &mut Work<'_>, table: &str, cells: &[[usize; 2]]) -> Result<(), EditError> {
    crate::ops::clear_cell_style_attributes(w, table, cells)
}

/// Swap Fill and Stroke on a text range (the toolbox's swap arrow with characters selected).
fn swap_text_paint(w: &mut Work<'_>, story: &str, start: &usize, end: &usize) -> Result<(), EditError> {
    crate::text::format::swap_paint::swap_range(w, story, *start, *end)
}

#[cfg(test)]
mod tests {
    #[test]
    fn generated_wire_types_are_current() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../app/renderer/src/generated/edit-commands.ts");
        assert_eq!(std::fs::read_to_string(path).unwrap().replace("\r\n", "\n"), super::typescript());
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../app/renderer/src/generated/doc-preferences.ts");
        assert_eq!(std::fs::read_to_string(path).unwrap().replace("\r\n", "\n"), folio_idml::docprefs::typescript());
    }
}
